# Build the predicted output from the demonstrated tile-projection rule, then validate dimensions and separators.
n=28
sep={4,9,14,19,24}
grid=[[8 if r in sep or c in sep else 0 for c in range(n)] for r in range(n)]
# Five complete 4x4 tile bands by five complete 4x4 tile columns; the final 3-cell edges remain untouched.
bands=[range(0,4),range(5,9),range(10,14),range(15,19),range(20,24)]
for tr, rows in enumerate(bands):
    for tc, cols in enumerate(bands):
        color = 6 if (tr==1 and tc==2) else (2 if (tr==1 or tc==0) else (3 if tc==2 else 0))
        if color:
            for r in rows:
                for c in cols:
                    grid[r][c]=color
assert len(grid)==28 and all(len(row)==28 for row in grid)
assert all(all(grid[r][c]==8 for c in range(28)) for r in sep)
assert all(all(grid[r][c]==8 for r in range(28)) for c in sep)
import json
print(json.dumps({'action':'submit','grid':grid},separators=(',',':')))

